def page(name,title,body,desc):
 (p/name).write_text(f'<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><meta name="description" content="{desc}"><meta name="theme-color" content="#141c20"><title>{title} | David Stroupe</title><link rel="stylesheet" href="style.css"></head><body>'+nav+'<main id="main">'+body+'</main>'+contact+'</body></html>')
def visual(kind,large=False):
 if kind=='automation': inner='<div class="flow"><div class="step">Request received</div><span class="arrow">→</span><div class="step">Structured intake</div><span class="arrow">→</span><div class="step">Shared record</div></div>'
 elif kind=='reporting': inner='<div class="board"><div class="panel"><span class="label">Reporting structure</span><h3>Readiness overview</h3><div class="row"><span>Summary</span><span>Leadership view</span></div><div class="row"><span>Supporting information</span><span>Detail view</span></div></div><div class="panel"><span class="label">Presentation → dashboard</span><p>Consolidated reporting<br>Shared context<br>Supporting detail</p></div></div>'
 elif kind=='portal': inner='<div class="board"><div class="panel"><span class="label">Registry structure</span><div class="row"><strong>Work item</strong><strong>Reporting field</strong></div><div class="row"><span>Caseload</span><span>Complexity</span></div><div class="row"><span>Request</span><span>Cycle time</span></div></div><div class="panel"><span class="label">From records to review</span><h3>Appraisal inputs</h3><span class="tag">Excel export</span></div></div>'
 else: inner='<div class="board"><div class="panel"><span class="label">Illustrative workspace</span><div class="row"><span>Reporting request</span><span class="tag">In review</span></div><div class="row"><span>Information update</span><span class="tag">In progress</span></div><div class="row"><span>Completed request</span><span class="tag">Complete</span></div></div><div class="panel"><span class="label">Information hierarchy</span><p style="font-size:22px;font-weight:bold;margin:12px 0">Overview</p><div class="bar" style="width:85%"></div><div class="bar" style="width:58%"></div><div class="bar" style="width:72%"></div><span class="label">Summary → detail</span></div></div>'
 return '<div class="visual '+('large' if large else '')+'" aria-label="Illustrative '+kind+' concept, not an actual work system"><div class="vtop"><strong>'+{'operations':'Operational workspace','reporting':'Executive reporting','automation':'Intake workflow','portal':'Performance portal'}[kind]+'</strong><span>Concept study</span></div>'+inner+'</div>'
cases=[
('operations','Operational dashboards','From a service ticket to a useful application.','Palantir Foundry Workshop · AIP','Leidos · August 2026 to present',

'The original request was to recreate several SharePoint tracking sites in Foundry. That would have moved the same experience to a different platform. I wanted to understand what the new application could do to make the work easier.',
'I started by reviewing the service tickets and checking the datasets and ontology objects already available. Most of the information was there. Where it was missing, it needed to be ingested before I could finish the build. I then looked for related data that could give users a fuller picture. I configured the dashboards myself, working as one of three builders who collaborate but own their individual builds.',
'I organized the experience around the organization a user needed to review. From that view, they could find related work, overdue tasks, upcoming items across 30, 60, and 90 days, and attached files. I also configured AIP Logic and Augmentation so users could ask questions and get a summary of related information. The aim was to make it easier to move from an overview to the details behind it.',
'Two builds have passed user acceptance testing. Two more are in testing, and a readiness dashboard is in development. Feedback on the completed builds was positive, including recognition during a weekly leadership meeting. Requested changes were small, such as button colors and placement. The completed dashboards bring related information into one place to support review and preparation.' ),
('reporting','Executive reporting','Bring scattered reporting into a shared view.','Power BI · Executive reporting','Addx Corporation · October 2025 to August 2026',
'A recurring leadership reporting process depended on manual preparation of a weekly presentation. Information needed to be consolidated into a view that senior leaders could use.',
'I built a Power BI readiness dashboard that brought reporting information together. I worked with leadership and users to translate operational needs into reporting requirements and dashboard designs.',
'The key change was the reporting format: a consolidated dashboard in place of a manually assembled presentation. I also used an interactive HTML mockup to communicate the proposed architecture during leadership briefings.',
'The dashboard replaced the manual weekly presentation preparation process. Leadership had a shared view instead of another presentation to assemble.'),
('automation','Request intake automation','Give incoming requests a consistent path.','Power Automate · SharePoint','Addx Corporation · October 2025 to August 2026',
'Onboarding requests required manual entry before the team could work with the information.',
'I built and deployed an automated ingestion pipeline using Power Automate and SharePoint to move incoming request information into the reporting process.',
'I used an event driven intake workflow so the process could begin when a request arrived. SharePoint supported the information workflow, with Power Automate handling the automated intake.',
'The pipeline eliminated manual entry for the onboarding requests covered by that workflow. This portfolio does not publish operational records or customer system details.'),
('portal','Performance and knowledge management','Make work easier to track and explain.','SharePoint · Tracking and reporting','Addx Corporation · October 2025 to August 2026',
'Team members needed a practical way to track caseload complexity and cycle times and prepare information for performance reviews.',
'I designed a performance portal and an interactive database registry to organize the work and support reporting.',
'I brought tracking and reporting into a shared portal and included an Excel export for appraisal inputs. The structure connected day to day records with the information needed for review.',
'The portal supported caseload and cycle time tracking and simplified preparation of appraisal inputs through an Excel export.')]
for slug,title,headline,tools,context,problem,approach,decisions,result in cases:
 body=f'<div class="intro"><a class="meta" href="index.html#work">← Selected work</a><p class="eyebrow">{tools}</p><h1>{headline}</h1><p class="lead">{title}</p></div>'+visual(slug,True)+'<p class="caption">Original illustration with fictional content. Not a screenshot or reconstruction of a customer system.</p>'
 body+=f'<div class="section case-grid"><aside><dl class="facts"><dt>Context</dt><dd>{context}</dd><dt>Contribution</dt><dd>Application development and reporting</dd><dt>Tools</dt><dd>{tools}</dd></dl></aside><article>'+''.join(f'<section><h2>{h}</h2><p>{t}</p></section>' for h,t in [('The problem',problem),('My approach',approach),('Design decisions',decisions)]+([('Making it easier to use','I worked through keyboard navigation, focus order, and contrast. I added hover feedback and tooltips to explain controls. I have not completed a formal accessibility review or screen reader testing, so I do not describe these dashboards as fully Section 508 compliant.'),('What I am working on next','I am developing custom widget prototypes for the two completed dashboards. These explore a more modern interface and bring in additional datasets and objects. They are still in progress.') ] if slug=='operations' else [])+[('The result',result)])+'</article></div>'
 page(slug+'.html',title,body,headline)
intro='''<section class="intro"><p class="eyebrow">David Stroupe / Data visualization & operational applications</p><h1>Clear information.<br>Decisions with context.</h1><p class="lead">I build operational dashboards and reporting tools for government teams and senior leaders.</p><div class="indexline"><span>U.S. Navy veteran</span><span>20+ years of DoD experience</span><span>Baltimore, Maryland</span></div><div class="actions"><a class="button" href="#work">Explore selected work ↓</a><a href="about.html">My background ↗</a></div></section>'''
body=intro+visual('operations',True)+'<p class="caption">Illustrative interface concept. Fictional content, not a government system.</p><section class="section" id="work"><div class="section-head"><h2>Selected work</h2><p class="meta">Dashboards, reporting, and the processes behind them.</p></div><p class="meta">These case studies explain my work in general terms. The visuals use fictional content and are not customer screenshots.</p><div class="work-grid">'
for i,(slug,title,headline,tools,*_) in enumerate(cases,1):body+=f'<a class="work" href="{slug}.html">{visual(slug)}<p class="eyebrow">0{i} / {tools}</p><h3>{title} ↗</h3><p>{headline}</p></a>'
body+='''</div></section><section class="section"><p class="eyebrow">How I work</p><p class="quote">Before I build, I ask what would actually make the work easier. That is where a useful dashboard starts.</p><a href="about.html">More about my approach ↗</a></section>'''
page('index.html','Data visualization & operational applications',body,'Operational dashboards, Power BI reporting, Power Automate workflows, and SharePoint applications by Navy veteran David Stroupe.')
page('about.html','About', '''<div class="intro"><p class="eyebrow">About David Stroupe</p><h1>Operational experience.<br>A focus on the person using the tool.</h1><p class="lead">I bring more than 20 years of Department of Defense experience to data visualization, reporting, and operational applications.</p></div><div class="text-page"><p>My career began in the U.S. Navy, working across personnel programs, administration, and career counseling. That work taught me to turn complicated requirements into information people can act on.</p><p>Today, I build operational dashboards and analytical tools at Leidos. I review incoming requests, assess the available data, and develop applications in Palantir Foundry Workshop. My earlier work includes Power BI reporting, Power Automate pipelines, and SharePoint portals.</p><h2>What guides my work</h2><p>Moving a process onto a new screen is only worth doing if it makes the work easier. I look at what users need, what information is available, and where the experience can improve.</p><h2>Developing my design practice</h2><p>I am enrolled in the Google UX Design certificate course and developing my skills in Figma. My course portfolio projects and an independent UX project will be added as they are completed.</p><h2>Experience</h2><p>Leidos · Addx Corporation · FedWriters · Booz Allen Hamilton · WWC Federal / WWC Global · United States Navy</p><p>My background spans operational dashboards, executive reporting, knowledge management, SharePoint administration, and personnel operations.</p><p class="note">This portfolio uses generic descriptions and original illustrations. It contains no customer screenshots, operational datasets, or program specific details.</p></div>''','David Stroupe is a U.S. Navy veteran and data visualization analyst with more than 20 years of DoD experience.')
page('accessibility.html','Accessibility', '''<div class="intro"><p class="eyebrow">Accessibility</p><h1>Designed to be usable.</h1></div><div class="text-page"><p>This site uses semantic page structure, visible keyboard focus, a skip link, descriptive links, responsive layouts, and reduced motion preferences. Information is presented in text rather than relying only on visuals or color.</p><p>I have checked the basics, but there is more to test. This site has not had a formal Section 508 review. I keep the checks and remaining work in the project’s accessibility notes on GitHub.</p><p>If you encounter a barrier, please contact me through LinkedIn and describe the page and the difficulty.</p></div>''','Accessibility information for David Stroupe’s portfolio.')
print('Built',len(list(p.glob('*.html'))),'pages')
